public sealed class SalesAnalyticsTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);private static Guid Id(JsonElement x)=>x.GetProperty("id").GetGuid();private static long V(JsonElement x)=>x.GetProperty("version").GetInt64();private static JsonElement E(object x)=>JsonSerializer.SerializeToElement(x,ApiJson.Options);private static decimal Net(JsonElement x)=>D(x.GetProperty("totals").GetProperty("net"));
 private async Task<DateOnly> Today()=>DateOnly.Parse((string)(await S("SELECT((now()AT TIME ZONE timezone)::date)::text FROM core.companies WHERE id=@c",("c",db.Company)))!);
 private async Task<string> Query()=>"from="+(await Today()).ToString("yyyy-MM-dd")+"&to="+(await Today()).AddDays(1).ToString("yyyy-MM-dd");
 private async Task<JsonElement> Report(HttpClient c,string extra="")=>await Get(c,"/sales-analytics/trends?"+await Query()+extra);
 private async Task<JsonElement> Facts(HttpClient c,string extra="")=>await Get(c,"/sales-analytics/facts?"+await Query()+extra);
 private async Task<JsonElement> Bridge(HttpClient c)=>await Get(c,"/sales-analytics/reconciliation?"+await Query());
 private sealed record Data(SalesData Sales,Guid Order,Guid Line,Guid Movement,string? Author=null,Guid? Membership=null);
 private async Task<Data> Order(HttpClient c,bool stock=false,bool direct=false,decimal quantity=3,bool salesAuthor=false,string basis="NON_CASH",string productName="Analytics service")
 {await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,basis,DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,stock?quantity*2.2m:0);if(!stock){var p=await Get(c,$"/products/{d.Product}");await Expect(await Send(c,HttpMethod.Put,$"/products/{d.Product}",new ProductMaintenance(p.GetProperty("sku").GetString()!,productName,p.GetProperty("taxCodeId").GetGuid(),ItemType:"SERVICE",WholePacks:false),1),HttpStatusCode.OK);}Guid order;string? author=null;Guid? membership=null;
  if(direct)order=(await Expect(await Send(c,HttpMethod.Post,"/sales-orders",new DirectOrderInput(d.Customer,d.Branch,d.Warehouse,[new(d.BoxUnit,Quantity:quantity,UnitPrice:100)],"Office order")),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();
  else{if(salesAuthor){var p=await Staff(db,"SALES",d);author=p.Subject;membership=p.Membership;}await using var authorApi=salesAuthor?new TestApi(db):null;using var other=salesAuthor?authorApi!.Authenticated(author!):null;var q=await Submitted(other??c,d.Draft(quantity)with{Lines=[new(d.BoxUnit,Quantity:quantity,UnitPrice:100)]});order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();}
  var line=(await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0].GetProperty("id").GetGuid();Guid movement=Guid.Empty;if(stock){await StockValuation.InitializeAsync(db.Owner,db.Company,d.Warehouse,d.Product,20.01m,"Analytics opening",DatabaseFixture.Issuer,db.Subject);var pick=Id(await Expect(await Send(c,HttpMethod.Post,$"/warehouse/orders/{order}/picks",new PickInput([new(line,quantity)]),1),HttpStatusCode.Created));await Expect(await Send(c,HttpMethod.Post,$"/warehouse/picks/{pick}/confirm",new DispatchInput("PICKUP","Customer","Docket"),1),HttpStatusCode.OK);movement=(await Get(c,$"/warehouse/orders/{order}/returnable")).GetProperty("movements")[0].GetProperty("stockMovementId").GetGuid();}return new(d,order,line,movement,author,membership);}
 private static async Task<JsonElement> Invoice(HttpClient c,Data d,decimal qty=3){var version=V(await Get(c,$"/sales-orders/{d.Order}/invoiceable"));return await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{d.Order}/invoices",new InvoiceInput([new(d.Line,qty)],"Completed"),version),HttpStatusCode.Created);}
 private static Guid IL(JsonElement i)=>Id(i.GetProperty("lines")[0]);
 private static Task<HttpResponseMessage> Amount(HttpClient c,JsonElement i,decimal net=25,decimal tax=2.5m,string? key=null)=>Send(c,HttpMethod.Post,$"/sales-invoices/{Id(i)}/amount-credit-notes",new AmountCreditInput("Adjustment",[new(IL(i),net,tax,"Price correction")]),key:key);
 private static Task<HttpResponseMessage> Credit(HttpClient c,JsonElement i,decimal quantity=1,Guid? returned=null)=>Send(c,HttpMethod.Post,$"/sales-invoices/{Id(i)}/credit-notes",new CreditNoteInput("Credit",[new(IL(i),quantity,returned)]));
 private async Task<JsonElement> Checkpoint(HttpClient c,Guid? customer=null,string? key=null)=>await Expect(await Send(c,HttpMethod.Post,"/sales-analytics/checkpoints",new SalesAnalyticsFilter(await Today(),(await Today()).AddDays(1),customer),key:key),HttpStatusCode.Created);
 [Fact]public async Task Empty_sales_report_and_checkpoint_export_have_zero_totals_and_no_financial_effects()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var live=await Report(c);Assert.Equal(0,Net(live));Assert.Empty(live.GetProperty("rows").EnumerateArray());Assert.Equal("RECONCILED",(await Bridge(c)).GetProperty("status").GetString());var p=await Checkpoint(c);Assert.Equal("SALES",p.GetProperty("snapshot").GetProperty("kind").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM accounting.journal_entries WHERE company_id=@c",("c",db.Company)));var operating=await Get(c,"/accounting/reports/operating?kind=SALES&"+await Query());Assert.Equal(0,Net(operating));}
 [Theory][InlineData("CASH")][InlineData("NON_CASH")]
 public async Task Invoice_minus_quantity_and_amount_credits_is_net_sales_independent_of_cash_GST_basis(string basis)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,basis:basis);var invoice=await Invoice(c,d);await Expect(await Credit(c,invoice),HttpStatusCode.Created);await Expect(await Amount(c,invoice),HttpStatusCode.Created);var r=await Report(c);Assert.Equal(175,Net(r));Assert.Equal(17.5m,D(r.GetProperty("totals").GetProperty("gst")));Assert.Equal(4.4m,D(r.GetProperty("totals").GetProperty("quantityByBaseUnit")[0].GetProperty("baseQuantity")));var facts=(await Facts(c)).GetProperty("items");Assert.Equal(3,facts.GetArrayLength());Assert.Equal(3,facts.EnumerateArray().Select(x=>x.GetProperty("factId").GetString()).Distinct().Count());Assert.Equal("RECONCILED",(await Bridge(c)).GetProperty("status").GetString());}
 [Fact]public async Task Tax_only_credit_changes_GST_but_not_revenue_or_quantity()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);var i=await Invoice(c,d);await Expect(await Amount(c,i,0,5),HttpStatusCode.Created);var r=await Report(c);Assert.Equal(300,Net(r));Assert.Equal(25,D(r.GetProperty("totals").GetProperty("gst")));Assert.Equal(6.6m,D(r.GetProperty("totals").GetProperty("quantityByBaseUnit")[0].GetProperty("baseQuantity")));Assert.Equal("RECONCILED",(await Bridge(c)).GetProperty("status").GetString());}
 [Fact]public async Task Physical_return_pending_financial_credit_is_not_a_second_revenue_reversal()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,true);var i=await Invoice(c,d);var returned=await Expect(await Send(c,HttpMethod.Post,$"/sales-orders/{d.Order}/returns",new SalesReturnInput(d.Sales.Warehouse,"RESTOCK","Return inspected",[new(d.Movement,1,IL(i))])),HttpStatusCode.Created);var pending=await Get(c,"/sales-analytics/pending-returns?"+await Query());Assert.Equal(1,pending.GetProperty("totalCount").GetInt32());Assert.Equal(300,Net(await Report(c)));var line=Id(returned.GetProperty("lines")[0]);await Expect(await Credit(c,i,1,line),HttpStatusCode.Created);Assert.Equal(200,Net(await Report(c)));Assert.Empty((await Report(c)).GetProperty("pendingReturns").EnumerateArray());var b=await Bridge(c);Assert.Equal("RECONCILED",b.GetProperty("status").GetString());Assert.Equal(13.34m,D(b.GetProperty("cost").GetProperty("sourceExpenseCost")));}
 [Fact]public async Task Receipt_refund_and_unapply_do_not_reduce_net_sales_again()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,basis:"CASH");var i=await Invoice(c,d);await Expect(await Send(c,HttpMethod.Post,$"/customers/{d.Sales.Customer}/receipts",new CustomerReceiptInput(330,"BANK_TRANSFER",Code(),[new(IL(i),330)])),HttpStatusCode.Created);var credit=await Expect(await Amount(c,i),HttpStatusCode.Created);var creditLine=Id(credit.GetProperty("lines")[0]);var before=Net(await Report(c));await Expect(await Send(c,HttpMethod.Post,$"/customers/{d.Sales.Customer}/refunds",new CustomerRefundInput(27.5m,Code(),"Refund paid",creditLine)),HttpStatusCode.Created);Assert.Equal(before,Net(await Report(c)));Assert.Equal(2,(await Facts(c)).GetProperty("totalCount").GetInt32());Assert.Equal("RECONCILED",(await Bridge(c)).GetProperty("status").GetString());}
 [Fact]public async Task Quote_author_attribution_survives_assignment_changes_and_direct_orders_start_unassigned()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,salesAuthor:true);var a=await Get(c,$"/sales-orders/{d.Order}/sales-attribution");var expected=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",d.Membership!.Value)))!;Assert.Equal(expected,a.GetProperty("salespersonId").GetGuid());await Invoice(c,d);await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",d.Membership.Value));Assert.Equal(expected,(await Facts(c)).GetProperty("items")[0].GetProperty("salespersonId").GetGuid());var direct=await Order(c,direct:true);var view=await Get(c,$"/sales-orders/{direct.Order}/sales-attribution");Assert.Equal("DIRECT_UNASSIGNED",view.GetProperty("basis").GetString());Assert.Equal(JsonValueKind.Null,view.GetProperty("salespersonId").ValueKind);}
 [Fact]public async Task Authorized_explicit_attribution_is_versioned_idempotent_and_frozen_by_first_invoice()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,direct:true);var p=await Staff(db,"SALES",d.Sales);var user=(Guid)(await S("SELECT user_id FROM identity.memberships WHERE company_id=@c AND id=@m",("c",db.Company),("m",p.Membership)))!;var key=Code();var input=new SalesAttributionInput(user,"Sales owner confirmed");var a=await Expect(await Send(c,HttpMethod.Put,$"/sales-orders/{d.Order}/sales-attribution",input,1,key),HttpStatusCode.OK);Assert.True(JsonElement.DeepEquals(a,await Expect(await Send(c,HttpMethod.Put,$"/sales-orders/{d.Order}/sales-attribution",input,1,key),HttpStatusCode.OK)));await Invoice(c,d);await Expect(await Send(c,HttpMethod.Put,$"/sales-orders/{d.Order}/sales-attribution",input,2),HttpStatusCode.Conflict);Assert.Equal(user,(await Facts(c)).GetProperty("items")[0].GetProperty("salespersonId").GetGuid());await Assert.ThrowsAsync<PostgresException>(()=>S("INSERT INTO sales.order_attributions(company_id,order_id,version,salesperson_id,basis,reason,created_by)VALUES(@c,@o,3,@u,'EXPLICIT','Forbidden',@u)",("c",db.Company),("o",d.Order),("u",db.Actor)));}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_attribution_replay_or_conflicting_versions_create_one_revision(bool replay)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,direct:true);var key=Code();var input=new SalesAttributionInput(db.Actor,"Attribution");var path=$"/sales-orders/{d.Order}/sales-attribution";var all=await Task.WhenAll(Send(c,HttpMethod.Put,path,input,1,key),Send(c,HttpMethod.Put,path,input,1,replay?key:Code()));Assert.Equal(replay?2:1,all.Count(x=>x.StatusCode==HttpStatusCode.OK));if(!replay)Assert.Single(all,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(2L,await S("SELECT count(*)FROM sales.order_attributions WHERE company_id=@c AND order_id=@o",("c",db.Company),("o",d.Order)));}
 [Fact]public async Task Invoice_and_attribution_race_preserves_one_frozen_origin()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,direct:true);var input=new SalesAttributionInput(db.Actor,"Racing invoice");var version=V(await Get(c,$"/sales-orders/{d.Order}/invoiceable"));var writes=await Task.WhenAll(Send(c,HttpMethod.Put,$"/sales-orders/{d.Order}/sales-attribution",input,1),Send(c,HttpMethod.Post,$"/sales-orders/{d.Order}/invoices",new InvoiceInput([new(d.Line,3)],"Done"),version));Assert.Equal(HttpStatusCode.Created,writes[1].StatusCode);Assert.Contains(writes[0].StatusCode,new[]{HttpStatusCode.OK,HttpStatusCode.Conflict});Assert.True((await Get(c,$"/sales-orders/{d.Order}/sales-attribution")).GetProperty("frozen").GetBoolean());Assert.Equal(300,Net(await Report(c)));}
 [Fact]public async Task Sales_role_only_sees_current_assigned_customers_not_company_GL_cost_or_checkpoints()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var one=await Order(c);var two=await Order(c);await Invoice(c,one);await Invoice(c,two);var p=await Staff(db,"SALES",one.Sales);using var sales=api.Authenticated(p.Subject);var r=await Report(sales);Assert.Equal(300,Net(r));Assert.All(r.GetProperty("rows").EnumerateArray(),x=>Assert.Equal(one.Sales.Customer,x.GetProperty("customerId").GetGuid()));Assert.False(r.TryGetProperty("reconciliation",out _));Assert.DoesNotContain("expenseCost",r.GetRawText());await Expect(await Send(sales,HttpMethod.Get,"/sales-analytics/reconciliation?"+await Query()),HttpStatusCode.Forbidden);await Expect(await Send(sales,HttpMethod.Post,"/sales-analytics/checkpoints",new SalesAnalyticsFilter(await Today(),(await Today()).AddDays(1))),HttpStatusCode.Forbidden);await Expect(await Send(sales,HttpMethod.Get,"/sales-analytics/facts?"+await Query()+$"&customerId={two.Sales.Customer}"),HttpStatusCode.Forbidden);await S("DELETE FROM identity.customer_assignments WHERE company_id=@c AND membership_id=@m",("c",db.Company),("m",p.Membership));Assert.Equal(0,Net(await Report(sales)));}
 [Theory][InlineData("WAREHOUSE")][InlineData("PROCUREMENT")]
 public async Task Unrelated_roles_cannot_read_sales_facts(string role)
 {await using var api=new TestApi(db);var p=await Staff(db,role);using var c=api.Authenticated(p.Subject);await Expect(await Send(c,HttpMethod.Get,"/sales-analytics/trends?"+await Query()),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Get,"/sales-analytics/facts?"+await Query()),HttpStatusCode.Forbidden);}
 [Fact]public async Task Cross_company_identifiers_and_checkpoints_are_not_visible()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);await Invoice(c,d);var point=await Checkpoint(c);using var other=api.Authenticated(company:db.OtherCompany);Assert.Equal(0,Net(await Report(other)));await Expect(await Send(other,HttpMethod.Get,$"/sales-analytics/checkpoints/{Id(point)}"),HttpStatusCode.NotFound);await Expect(await Send(other,HttpMethod.Get,"/sales-analytics/trends?"+await Query()+$"&customerId={d.Sales.Customer}"),HttpStatusCode.Forbidden);}
 [Theory][InlineData("reports.sales.read")][InlineData("reports.sales.all")][InlineData("reports.sales.reconcile")][InlineData("customers.all")][InlineData("inventory.cost.read")]
 public async Task Revoked_permissions_block_cached_checkpoint_and_export(string cap)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var key=Code();var point=await Checkpoint(c,key:key);await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code=@p",("c",db.Company),("p",cap));await Expect(await Send(c,HttpMethod.Post,"/sales-analytics/checkpoints",new SalesAnalyticsFilter(await Today(),(await Today()).AddDays(1)),key:key),HttpStatusCode.Forbidden);await Expect(await Send(c,HttpMethod.Post,$"/operating-report-runs/{Id(point)}/export",version:1),HttpStatusCode.Forbidden);}
 [Fact]public async Task Checkpoint_is_frozen_rebuild_reads_current_sources_and_replays_never_post_again()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);var i=await Invoice(c,d);var first=await Checkpoint(c);await Expect(await Amount(c,i),HttpStatusCode.Created);var second=await Checkpoint(c);Assert.Equal(300,Net(first.GetProperty("snapshot")));Assert.Equal(275,Net(second.GetProperty("snapshot")));Assert.NotEqual(first.GetProperty("snapshot").GetProperty("sourceHash").GetString(),second.GetProperty("snapshot").GetProperty("sourceHash").GetString());var stored=await Get(c,$"/sales-analytics/checkpoints/{Id(first)}");Assert.True(JsonElement.DeepEquals(first,stored));await Assert.ThrowsAsync<PostgresException>(()=>S("UPDATE accounting.operating_report_runs SET snapshot='{}'WHERE company_id=@c AND id=@id",("c",db.Company),("id",Id(first))));}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_checkpoint_replays_or_independent_rebuilds_are_complete_snapshots(bool replay)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);await Invoice(c,d);var key=Code();var points=await Task.WhenAll(Checkpoint(c,key:key),Checkpoint(c,key:replay?key:Code()));Assert.Equal(replay?1:2,points.Select(Id).Distinct().Count());Assert.All(points,p=>Assert.Equal(300,Net(p.GetProperty("snapshot"))));Assert.Equal(1L,await S("SELECT count(*)FROM sales.invoices WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Reader_and_checkpoint_during_uncommitted_credit_see_one_source_and_GL_snapshot()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);var i=await Invoice(c,d);await using(var session=await db.SessionAsync()){await Sql.RowsAsync(session,"SELECT sales.post_amount_credit_note(@i,'Pending',@lines::jsonb)",default,("i",Id(i)),("lines",JsonSerializer.Serialize(new[]{new{invoiceLineId=IL(i),net=25,tax=2.5m,description="Pending"}})));var point=await Checkpoint(c);Assert.Equal(300,Net(point.GetProperty("snapshot")));Assert.Equal("RECONCILED",point.GetProperty("snapshot").GetProperty("reconciliation").GetProperty("status").GetString());await session.Transaction.CommitAsync();}Assert.Equal(275,Net(await Report(c)));Assert.Equal("RECONCILED",(await Bridge(c)).GetProperty("status").GetString());}
 [Theory][InlineData("checkpoint")][InlineData("attribution")]
 public async Task Late_audit_failure_rolls_back_checkpoint_or_assignment_then_same_key_can_retry(string kind)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,direct:true);var key=Code();var filter=new SalesAnalyticsFilter(await Today(),(await Today()).AddDays(1));Task<HttpResponseMessage> Run()=>kind=="checkpoint"?Send(c,HttpMethod.Post,"/sales-analytics/checkpoints",filter,key:key):Send(c,HttpMethod.Put,$"/sales-orders/{d.Order}/sales-attribution",new SalesAttributionInput(db.Actor,"Audit"),1,key);var action=kind=="checkpoint"?"sales.analytics_checkpoint":"sales.attribution_assigned";await S($"CREATE FUNCTION sales.test_c07_fail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='{action}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c07_fail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION sales.test_c07_fail()");try{await Expect(await Run(),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM accounting.operating_report_runs WHERE company_id=@c",("c",db.Company)));Assert.Equal(1L,await S("SELECT count(*)FROM sales.order_attributions WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c07_fail ON platform.audit_events;DROP FUNCTION sales.test_c07_fail()");}await Expect(await Run(),kind=="checkpoint"?HttpStatusCode.Created:HttpStatusCode.OK);}
 [Fact]public async Task Renaming_product_or_unit_does_not_change_historical_fact_labels_or_quantity_unit()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);await Invoice(c,d);var original=(await Facts(c)).GetProperty("items")[0];await S("UPDATE catalog.products SET sku=@s,name='Renamed'WHERE company_id=@c AND id=@p;UPDATE catalog.uoms SET code='SQM_RENAMED'WHERE company_id=@c AND id=(SELECT base_uom_id FROM catalog.products WHERE company_id=@c AND id=@p)",("c",db.Company),("p",d.Sales.Product),("s",Code()));var now=(await Facts(c)).GetProperty("items")[0];Assert.Equal(original.GetProperty("sku").GetString(),now.GetProperty("sku").GetString());Assert.Equal(original.GetProperty("baseUnitCode").GetString(),now.GetProperty("baseUnitCode").GetString());Assert.Equal(original.GetProperty("baseUomId").GetGuid(),now.GetProperty("baseUomId").GetGuid());}
 [Fact]public async Task Comparisons_with_no_prior_sales_are_null_and_pagination_does_not_change_totals()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Order(c);var b=await Order(c);await Invoice(c,a);await Invoice(c,b);var r=await Report(c,"&pageSize=1");Assert.Equal(600,Net(r));Assert.Equal(2,r.GetProperty("totalCount").GetInt32());Assert.Single(r.GetProperty("rows").EnumerateArray());var previous=r.GetProperty("totals").GetProperty("previousPeriod");Assert.Equal("NO_BASELINE",previous.GetProperty("status").GetString());Assert.Equal(JsonValueKind.Null,previous.GetProperty("percent").ValueKind);var next=await Report(c,"&page=2&pageSize=1");Assert.Equal(600,Net(next));Assert.NotEqual(r.GetProperty("rows")[0].GetProperty("productId").GetGuid(),next.GetProperty("rows")[0].GetProperty("productId").GetGuid());}
 [Theory][InlineData("bucket=BAD")][InlineData("pageSize=101")][InlineData("page=-1")][InlineData("branchId=00000000-0000-0000-0000-000000000000")]
 public async Task Invalid_filters_fail_cleanly(string extra)
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Expect(await Send(c,HttpMethod.Get,"/sales-analytics/trends?"+await Query()+"&"+extra),HttpStatusCode.UnprocessableEntity);}
 [Theory][InlineData("app","SELECT *FROM sales.net_sales_source")][InlineData("app","DELETE FROM sales.order_attributions")][InlineData("worker","SELECT sales.analytics_report('{}')")][InlineData("portal","SELECT sales.analytics_facts('{}')")]
 public async Task Restricted_logins_cannot_bypass_analytics_or_source_boundaries(string role,string sql)
 {await using var con=new NpgsqlConnection(role=="app"?db.App:role=="worker"?db.Worker:db.Portal);await con.OpenAsync();await using var cmd=new NpgsqlCommand(sql,con);Assert.Equal("42501",(await Assert.ThrowsAsync<PostgresException>(()=>cmd.ExecuteScalarAsync())).SqlState);}
 [Fact]public async Task OpenApi_includes_trends_facts_checkpoints_and_attribution()
 {await using var api=new TestApi(db);using var c=api.CreateClient();var spec=await c.GetFromJsonAsync<JsonElement>("/openapi/v1.json");foreach(var path in new[]{"/api/v1/sales-analytics/trends","/api/v1/sales-analytics/facts","/api/v1/sales-analytics/checkpoints","/api/v1/sales-orders/{id}/sales-attribution"})Assert.True(spec.GetProperty("paths").TryGetProperty(path,out _));}

 private sealed class Renderer:IPdfRenderer{public Task<byte[]>RenderAsync(JsonElement p,CancellationToken ct)=>throw new InvalidOperationException("Unexpected PDF");}
 private sealed class Scanner:IFileScanner{public Task<bool>IsCleanAsync(byte[]p,CancellationToken ct)=>throw new InvalidOperationException("Unexpected scan");}
 private sealed class Mailer:IDocumentMailer{public Task<string>SendAsync(Guid id,JsonElement p,CancellationToken ct)=>throw new InvalidOperationException("Unexpected email");}
 private sealed class RetryExporter:IReportExporter{public Task<byte[]>RenderAsync(JsonElement x,CancellationToken ct)=>throw new DocumentWorkException("test_retry",WorkFailure.Retry);}
 private async Task ExportJob(Guid id,IReportExporter? exporter=null)
 {await S("UPDATE platform.document_jobs SET state='FAILED'WHERE company_id<>@c AND state IN('QUEUED','RETRY','PROCESSING');UPDATE platform.document_jobs SET available_at=now()-interval '1 day'WHERE company_id=@c AND id=@id",("c",db.Company),("id",id));await using var source=NpgsqlDataSource.Create(db.Worker);Assert.True(await new DocumentWorker(source,new Renderer(),new Scanner(),new Mailer(),exporter).ProcessOneAsync());}
 [Fact]public async Task Sales_CSV_export_uses_frozen_facts_escapes_formulas_and_retries_without_reposting()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c,productName:"=SUM(1,2)");await Invoice(c,d);var point=await Checkpoint(c);var key=Code();var job=Id(await Expect(await Send(c,HttpMethod.Post,$"/operating-report-runs/{Id(point)}/export",version:1,key:key),HttpStatusCode.Accepted));var same=await Expect(await Send(c,HttpMethod.Post,$"/operating-report-runs/{Id(point)}/export",version:1,key:key),HttpStatusCode.Accepted);Assert.Equal(job,Id(same));await ExportJob(job,new RetryExporter());Assert.Equal("RETRY",(await Get(c,$"/document-jobs/{job}")).GetProperty("state").GetString());await ExportJob(job);var finished=await Get(c,$"/document-jobs/{job}");Assert.Equal("SUCCEEDED",finished.GetProperty("state").GetString());var file=finished.GetProperty("outputFileId").GetGuid();var bytes=await c.GetByteArrayAsync($"/api/v1/files/{file}/content");var csv=Encoding.UTF8.GetString(bytes);Assert.Contains("SALES",csv);Assert.Contains("'=SUM(1,2)",csv);Assert.Contains(point.GetProperty("sha256").GetString()!,csv);Assert.Contains("Previous net AUD",csv);Assert.Equal(1L,await S("SELECT count(*)FROM sales.invoices WHERE company_id=@c",("c",db.Company)));await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='reports.sales.read'",("c",db.Company));using var denied=await c.GetAsync($"/api/v1/files/{file}/content");Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);}
