 public async Task Reporting_roles_have_explicit_default_sales_access(string role)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);await Invoice(c,d);var p=await Staff(db,role);using var staff=api.Authenticated(p.Subject);Assert.Equal(300,Net(await Report(staff)));if(role!="OFFICE")Assert.Equal("RECONCILED",(await Bridge(staff)).GetProperty("status").GetString());}
 [Fact]public async Task Later_purchase_variance_is_separate_cost_evidence_and_does_not_rewrite_invoice_sales()
 {await using var api=new TestApi(db);using var c=api.Authenticated();await CompanyTaxSettings.ConfigureAsync(db.Owner,db.Company,true,"NON_CASH",DatabaseFixture.Issuer,db.Subject);var d=await Setup(db,c,0);var sid=await Create(c,"/suppliers",new SupplierMaintenance(Code(),"Cost supplier",null));var po=await Expect(await Send(c,HttpMethod.Post,"/purchase-orders",new Htt.Host.Api.Purchasing.PurchaseOrderInput(sid,d.Warehouse,[new(d.BoxUnit,2,10)])),HttpStatusCode.Created);var oid=Id(po.GetProperty("order"));po=await Expect(await Send(c,HttpMethod.Post,$"/purchase-orders/{oid}/confirm",version:1),HttpStatusCode.OK);var receipt=await Expect(await Send(c,HttpMethod.Post,$"/purchase-orders/{oid}/receipts",new Htt.Host.Api.Purchasing.PurchaseReceiptInput(Code(),[new(Id(po.GetProperty("lines")[0]),2)]),2),HttpStatusCode.Created);var q=await Submitted(c,d.Draft(1));var order=(await Expect(await Approve(c,q.Id,q.Version),HttpStatusCode.Created)).GetProperty("orderId").GetGuid();var line=Id((await Get(c,$"/sales-orders/{order}")).GetProperty("lines")[0]);var pick=Id(await Expect(await Send(c,HttpMethod.Post,$"/warehouse/orders/{order}/picks",new PickInput([new(line,1)]),1),HttpStatusCode.Created));await Expect(await Send(c,HttpMethod.Post,$"/warehouse/picks/{pick}/confirm",new DispatchInput("PICKUP","Buyer","Docket"),1),HttpStatusCode.OK);var invoice=await Invoice(c,new(d,order,line,Guid.Empty),1);var before=await Checkpoint(c);var today=await Today();var bill=new Htt.Host.Api.Purchasing.SupplierBillInput(sid,Code(),today,today.AddDays(30),today,[new(Id(receipt.GetProperty("lines")[0]),2,24,2.4m)],"Invoice",today);await Expect(await Send(c,HttpMethod.Post,"/supplier-bills/with-variance",new Htt.Host.Api.Purchasing.SupplierBillVarianceInput(bill,"Approved price variance")),HttpStatusCode.Created);Assert.Equal(Net(before.GetProperty("snapshot")),Net(await Report(c)));var bridge=await Bridge(c);Assert.Equal("RECONCILED",bridge.GetProperty("status").GetString());Assert.Equal(2,D(bridge.GetProperty("cost").GetProperty("unallocatedPurchaseVariance")));Assert.Equal(12,D(bridge.GetProperty("cost").GetProperty("sourceExpenseCost")));Assert.Equal("SOURCE_EVENT_NO_INVOICE_ALLOCATION",bridge.GetProperty("cost").GetProperty("allocationBasis").GetString());}
 [Fact]public async Task Other_business_revenue_bridges_to_GL_without_becoming_invoice_sales()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);await Invoice(c,d);var date=await Today();var doc=(Guid)(await S("INSERT INTO platform.documents(company_id,document_type,business_date,created_by)VALUES(@c,'ANALYTICS_OTHER_REVENUE',@date,@actor)RETURNING id",("c",db.Company),("date",date),("actor",db.Actor)))!;await using(var session=await db.SessionAsync()){await Sql.RowsAsync(session,"SELECT accounting.post_journal(@doc,1,'ANALYTICS_TEST',@date,'Other revenue',jsonb_build_array(jsonb_build_object('accountId',(SELECT id FROM accounting.accounts WHERE company_id=core.current_company()AND code='1000'),'debit',20),jsonb_build_object('accountId',(SELECT id FROM accounting.accounts WHERE company_id=core.current_company()AND code='4000'),'credit',20)))",default,("doc",doc),("date",date));await session.Transaction.CommitAsync();}var bridge=await Bridge(c);Assert.Equal(300,D(bridge.GetProperty("revenue").GetProperty("sourceNet")));Assert.Equal(20,D(bridge.GetProperty("revenue").GetProperty("otherRevenueGl")));Assert.Equal(320,D(bridge.GetProperty("revenue").GetProperty("allBusinessRevenueGl")));Assert.Equal("RECONCILED",bridge.GetProperty("status").GetString());Assert.Equal(300,Net(await Report(c)));}


 [Fact]public async Task Posted_invoice_rejects_extra_journal_and_report_remains_reconciled()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);var invoice=await Invoice(c,d);var date=await Today();await using(var session=await db.SessionAsync()){var error=await Assert.ThrowsAsync<PostgresException>(()=>Sql.RowsAsync(session,"SELECT accounting.post_journal(@doc,1,'C07_EXTRA_JOURNAL',@date,'Rejected extra source',jsonb_build_array(jsonb_build_object('accountId',(SELECT id FROM accounting.accounts WHERE company_id=core.current_company()AND code='1000'),'debit',1),jsonb_build_object('accountId',(SELECT id FROM accounting.accounts WHERE company_id=core.current_company()AND code='4000'),'credit',1)))",default,("doc",Id(invoice)),("date",date)));Assert.Equal("23514",error.SqlState);}var bridge=await Bridge(c);Assert.Equal("RECONCILED",bridge.GetProperty("status").GetString());Assert.Equal(0,D(bridge.GetProperty("revenue").GetProperty("difference")));Assert.Equal(300,Net(await Report(c)));}
 [Fact]public async Task Credit_committing_between_fact_build_and_GL_bridge_cannot_split_checkpoint_snapshot()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var d=await Order(c);var invoice=await Invoice(c,d);var original=(string)(await S("SELECT pg_get_functiondef('sales.analytics_report(jsonb)'::regprocedure)"))!;var key=Random.Shared.Next(1,int.MaxValue);var gated=original.Replace("RETURN result;",$"IF core.current_company()='{db.Company}'::uuid THEN PERFORM pg_advisory_xact_lock(741047,{key});END IF;RETURN result;");Assert.NotEqual(original,gated);await using var gate=new NpgsqlConnection(db.Owner);await gate.OpenAsync();await using var tx=await gate.BeginTransactionAsync();await using(var cmd=new NpgsqlCommand("SELECT pg_advisory_xact_lock(741047,@key)",gate,tx)){cmd.Parameters.AddWithValue("key",key);await cmd.ExecuteNonQueryAsync();}Task<JsonElement>? pending=null;var released=false;
 try{await S(gated);pending=Checkpoint(c);var waiting=false;for(var attempt=0;attempt<100;attempt++){waiting=(long)(await S("SELECT count(*)FROM pg_locks WHERE locktype='advisory'AND classid=741047::oid AND objid=@key::oid AND NOT granted",("key",key)))!>0;if(waiting)break;await Task.Delay(10);}Assert.True(waiting,"Snapshot read did not reach controlled boundary.");await Expect(await Amount(c,invoice),HttpStatusCode.Created);await tx.CommitAsync();released=true;var point=await pending;Assert.Equal(300,Net(point.GetProperty("snapshot")));Assert.Equal(300,D(point.GetProperty("snapshot").GetProperty("reconciliation").GetProperty("revenue").GetProperty("sourceNet")));}
 finally{if(!released)await tx.RollbackAsync();if(pending is not null)try{await pending;}catch(Exception){}await S(original);}Assert.Equal(275,Net(await Report(c)));}
}
